const CATS=['全部','收藏','荤菜','素菜','主食','汤羹','蒸菜','早餐','一锅出','其他'];
const INV_CATS=['保鲜','冷藏','常温'];
const DB_NAME='family-kitchen-db', DB_VERSION=2, STORE='state';
document.head.insertAdjacentHTML('beforeend','<style>.authPage{min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(180deg,#fff7ed,#fff)}.authCard{width:min(430px,100%);background:#fff;border:1px solid #ececec;border-radius:24px;padding:28px;box-shadow:0 18px 60px #6d3b0014}.authCard h1{text-align:center;margin:8px 0}.authLogo{text-align:center;font-size:58px}.authCard .primary{width:100%;font-weight:700}</style>');
