let db, saveRunner=null, saveRequested=0, saveCommitted=0, saveShowRequested=false, deferredSaveTimer=null, deferredIdleSave=null, view='首页', cat='全部', query='', overlay=null, timer=null, sessionKey=null, currentAuth=null, pendingLegacy=null;
let state={version:3,recipes:[],plans:{},inventory:[],shopping:[],updatedAt:Date.now()};
const selectedPurchases=new Set();
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const id=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),2400)}
function openDB(){return new Promise((ok,no)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
function dbGet(key='main'){return new Promise((ok,no)=>{const r=db.transaction(STORE).objectStore(STORE).get(key);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
function dbSet(key,value,remove){return new Promise((ok,no)=>{const tx=db.transaction(STORE,'readwrite'),s=tx.objectStore(STORE);s.put(value,key);if(remove)s.delete(remove);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function dbCreateVault(auth,vault){return new Promise((ok,no)=>{const tx=db.transaction(STORE,'readwrite'),s=tx.objectStore(STORE);s.put(auth,'auth');s.put(vault,'vault');s.put(vault,'vault_backup');s.delete('main');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function dbCommitVault(vault){return new Promise((ok,no)=>{const tx=db.transaction(STORE,'readwrite'),s=tx.objectStore(STORE);s.put(vault,'vault');s.put(vault,'vault_backup');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function dbRestorePackage(pkg){return new Promise((ok,no)=>{const tx=db.transaction(STORE,'readwrite'),s=tx.objectStore(STORE);s.put(pkg.auth,'auth');s.put(pkg.vault,'vault');s.put(pkg.vault,'vault_backup');tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function b64(bytes){let binary='';const size=32768;for(let i=0;i<bytes.length;i+=size)binary+=String.fromCharCode(...bytes.subarray(i,i+size));return btoa(binary)}
const unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function deriveKey(password,salt){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptState(data,key){const iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(data)));return{iv:b64(iv),data:b64(new Uint8Array(cipher)),v:1}}
async function decryptState(vault,key){const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(vault.iv)},key,unb64(vault.data));return JSON.parse(new TextDecoder().decode(plain))}
function normalize(x={}){const recipes=(x.recipes||[]).map(r=>({...r,id:r.id||id(),favorite:!!r.favorite,createdAt:r.createdAt||Date.now(),updatedAt:r.updatedAt||Date.now(),lastUsed:r.lastUsed||0,ingredients:Array.isArray(r.ingredients)?r.ingredients:String(r.ingredients||'').split('\n').filter(Boolean).map(line=>({id:id(),name:line,amount:'',unit:''})),steps:Array.isArray(r.steps)?r.steps:String(r.steps||'').split('\n').filter(Boolean).map(text=>({id:id(),text,photo:''}))}));const inventory=Array.isArray(x.inventory)?x.inventory.map(i=>({...i,id:i.id||id(),category:INV_CATS.includes(i.category)?i.category:'常温'})):[];return{version:5,recipes,plans:x.plans||{},inventory,shopping:Array.isArray(x.shopping)?x.shopping:[],planLedger:x.planLedger||{},ledgerReady:!!x.ledgerReady,updatedAt:x.updatedAt||Date.now()}}
function cleanupState(){const keep=new Set(days(7).map(x=>x.key));Object.keys(state.plans).forEach(day=>{if(!keep.has(day))delete state.plans[day]});Object.keys(state.planLedger).forEach(key=>{if(!keep.has(key.split('|')[0]))delete state.planLedger[key]});state.shopping=state.shopping.filter(x=>x&&x.name&&!x.done)}
function cancelDeferredSave(){if(deferredSaveTimer){clearTimeout(deferredSaveTimer);deferredSaveTimer=null}if(deferredIdleSave&&'cancelIdleCallback'in window){cancelIdleCallback(deferredIdleSave);deferredIdleSave=null}}
function saveLater(){cancelDeferredSave();const run=()=>{deferredSaveTimer=null;deferredIdleSave=null;save().catch(()=>{})};if('requestIdleCallback'in window)deferredIdleSave=requestIdleCallback(run,{timeout:3000});else deferredSaveTimer=setTimeout(run,1500)}
function save(show=false){if(!sessionKey)return Promise.reject(Error('应用已锁定'));cancelDeferredSave();saveRequested++;saveShowRequested||=show;if(saveRunner)return saveRunner;const key=sessionKey;saveRunner=new Promise(resolve=>setTimeout(resolve,0)).then(async()=>{while(saveCommitted<saveRequested){const target=saveRequested;cleanupState();state.updatedAt=Date.now();const snapshot=structuredClone(state),vault=await encryptState(snapshot,key);await dbCommitVault(vault);saveCommitted=target}if(saveShowRequested)toast('已加密保存到本机');scheduleLanSync()}).catch(e=>{console.error(e);toast(e?.name==='QuotaExceededError'?'存储空间不足，请立即导出备份':'保存失败，数据尚未写入，请勿刷新');throw e}).finally(()=>{saveRunner=null;saveShowRequested=false});return saveRunner}
function authScreen(mode,auth={}){$('#app').innerHTML=`<main class="authPage"><section class="authCard"><div class="authLogo">🍲</div><h1>我的家庭厨房</h1><p class="muted">${mode==='setup'?'首次使用，请设置本机账号和密码。':'请输入你的家庭厨房密码。'}</p><form id="authForm" data-mode="${mode}"><div class="field"><label>用户名</label><input id="authUser" autocomplete="username" value="${esc(auth.username||'')}" required></div><div class="field"><label>密码</label><input id="authPass" type="password" autocomplete="${mode==='setup'?'new-password':'current-password'}" minlength="6" required></div>${mode==='setup'?'<div class="field"><label>确认密码</label><input id="authConfirm" type="password" autocomplete="new-password" minlength="6" required></div><p class="muted"><small>密码无法找回。忘记密码后，加密数据将无法恢复，请务必保存好密码和定期导出的备份。</small></p>':''}<button class="btn primary" type="submit">${mode==='setup'?'创建私人厨房':'解锁'}</button><p id="authError" class="danger"></p></form>${mode==='setup'?'<hr><button class="btn" data-lan-restore>从家庭电脑恢复已有数据</button>':''}</section></main>`}
async function setupAccount(user,password){const salt=crypto.getRandomValues(new Uint8Array(16)),key=await deriveKey(password,salt),auth={username:user,salt:b64(salt),iterations:250000};state=normalize(pendingLegacy||state);migratePlanLedger();const vault=await encryptState(state,key);await dbCreateVault(auth,vault);localStorage.removeItem('family-recipes-v1');currentAuth=auth;sessionKey=key;render();toast('私人厨房已创建，数据已加密')}
async function unlockAccount(user,password){if(user!==currentAuth.username)throw Error('用户名或密码不正确');const key=await deriveKey(password,unb64(currentAuth.salt));let vault=await dbGet('vault'),data;try{data=await decryptState(vault,key)}catch{vault=await dbGet('vault_backup');data=await decryptState(vault,key);await dbSet('vault',vault);toast('已从本地安全副本恢复数据')}sessionKey=key;state=normalize(data);const changed=migratePlanLedger();cleanupState();render();if(changed)await save();else scheduleLanSync()}
async function changeUsername(){if(!sessionKey||!currentAuth)return toast('请先登录私人厨房');const next=(prompt('请输入新的用户名',currentAuth.username||'')||'').trim();if(!next)return;if(next.length>40)return toast('用户名不能超过40个字符');if(next===currentAuth.username)return toast('用户名没有变化');const updated={...currentAuth,username:next};try{await dbSet('auth',updated);currentAuth=updated;render();setLanStatus('用户名已更新，请在需要时立即同步');toast('用户名已更改，密码和全部数据保持不变')}catch(e){console.error(e);toast('用户名修改失败，请重试')}}
function photo(src,cls='hero'){return src?`<img class="${cls}" src="${src}" alt="" loading="lazy" decoding="async">`:`<div class="${cls} placeholder">🍲</div>`}
const cardHtmlCache=new WeakMap();
function card(r){const old=cardHtmlCache.get(r);if(old&&old.name===r.name&&old.cat===r.cat&&old.photo===r.photo&&old.favorite===r.favorite)return old.html;const html=`<article class="card"><button class="cardMedia" data-open="${r.id}">${r.photo?`<img src="${r.photo}" alt="${esc(r.name)}" loading="lazy" decoding="async" fetchpriority="low">`:'<span class="placeholder">🍲</span>'}</button><button class="heart" data-fav="${r.id}" aria-label="收藏">${r.favorite?'♥':'♡'}</button><div class="cardName">${esc(r.name)}</div><div class="cardMeta">${esc(r.cat||'其他')}</div></article>`;cardHtmlCache.set(r,{name:r.name,cat:r.cat,photo:r.photo,favorite:r.favorite,html});return html}
function nav(){return `<nav class="bottom"><div class="bottomInner">${[['首页','⌂'],['计划','▦'],['库存','▣'],['搜索','⌕'],['我的','♙']].map(([n,i])=>`<button data-view="${n}" class="${view===n?'active':''}"><span>${i}</span>${n}</button>`).join('')}</div></nav>`}
function shell(body,title='我的家庭厨房',fab=''){return `<div class="shell"><header class="top"><h1>${title}</h1>${view==='首页'?'<button class="btn" data-view="我的">备份</button>':''}</header>${body}${fab?`<button class="fab" data-action="${fab}" aria-label="添加">＋</button>`:''}${nav()}</div>`}
function gridColumns(){const value=Number(localStorage.getItem('family-kitchen-grid-columns')||2);return[2,3,4].includes(value)?value:2}
function grid(rs){return rs.length?`<div class="grid" style="grid-template-columns:repeat(${gridColumns()},minmax(0,1fr))">${rs.map(card).join('')}</div>`:'<div class="empty">这里还没有内容<br><small>点击右下角“＋”开始添加</small></div>'}
function goTop(){requestAnimationFrame(()=>{window.scrollTo(0,0);document.scrollingElement.scrollTop=0;const active=$('.tabs .active'),tabs=$('.tabs');if(active&&tabs)tabs.scrollLeft=Math.max(0,active.offsetLeft-tabs.clientWidth/2+active.clientWidth/2)})}
function foldPrefs(){try{return JSON.parse(localStorage.getItem('family-kitchen-folds')||'{}')}catch{return{}}}
function isFolded(key){return!!foldPrefs()[key]}
function toggleFold(key){const prefs=foldPrefs();prefs[key]=!prefs[key];localStorage.setItem('family-kitchen-folds',JSON.stringify(prefs));render()}
function foldHeader(key,title,count=''){const folded=isFolded(key);return `<button class="foldHeader" data-fold="${esc(key)}" aria-expanded="${!folded}"><h2>${esc(title)}</h2><span>${count?`<span class="badge">${count}</span> `:''}${folded?'▸':'▾'}</span></button>`}
const recipeSearchCache=new WeakMap(),planSearchCache=new WeakMap();
function recipeSearchText(r,planOnly=false){const cache=planOnly?planSearchCache:recipeSearchCache;if(cache.has(r))return cache.get(r);const parts=planOnly?[r.name,r.cat,...r.ingredients.map(x=>x.name)]:[r.name,r.description,r.cat,...r.ingredients.flatMap(x=>[x.name,x.amount,x.unit]),...r.steps.map(x=>x.text)];const text=parts.filter(Boolean).join('\n').toLocaleLowerCase('zh-CN');cache.set(r,text);return text}
function searchRecipes(term,planOnly=false){const needle=String(term||'').trim().toLocaleLowerCase('zh-CN');return needle?state.recipes.filter(r=>recipeSearchText(r,planOnly).includes(needle)):state.recipes}
function lanConfig(){try{const c=JSON.parse(localStorage.getItem('family-kitchen-lan')||'{}');if(!c.url&&location.protocol==='https:'&&location.port==='9443')c.url=location.origin;return c}catch{return{}}}
function render(){let body='';if(view==='首页'){let recent=[...state.recipes].sort((a,b)=>(b.lastUsed||b.updatedAt)-(a.lastUsed||a.updatedAt)).slice(0,6);body=`<div class="tabs">${CATS.map(x=>`<button data-cat="${x}" class="${cat===x?'active':''}">${x}</button>`).join('')}</div>${grid(state.recipes.filter(r=>(cat==='全部'||cat==='收藏'&&r.favorite||r.cat===cat)))}${state.recipes.length?`<section class="section"><div class="sectionTitle"><h2>最近使用</h2></div>${recent.map(r=>`<div class="row" data-open="${r.id}"><b>${esc(r.name)}</b><span>›</span></div>`).join('')}</section>`:''}`;$('#app').innerHTML=shell(body,'我的家庭厨房','recipe')}
else if(view==='搜索'){body=`<section class="section"><input class="search" id="searchBox" value="${esc(query)}" placeholder="搜索菜名、食材、分类或步骤" autocomplete="off" enterkeyhint="search"></section><div id="searchResults">${grid(searchRecipes(query))}</div>`;$('#app').innerHTML=shell(body,'搜索');requestAnimationFrame(()=>$('#searchBox')?.focus())}
else if(view==='计划'){const recipeNames=new Map(state.recipes.map(r=>[r.id,r.name]));body=`<section class="section"><p class="muted">始终显示今天和未来 6 天。过期计划会自动清理，食材会汇总到采购清单。</p>${days(7).map(d=>{let p=planIds(d.key),names=p.map(i=>recipeNames.get(i)).filter(Boolean);let legacy=typeof state.plans[d.key]==='string'?state.plans[d.key]:'';return `<div class="row"><div><b>${d.label}</b><div class="muted">${esc(names.join('、')||legacy||'暂无计划')}</div></div><button class="btn" data-plan="${d.key}">选择菜谱</button></div>`}).join('')}</section>`;$('#app').innerHTML=shell(body,'7 天菜单')}
else if(view==='库存'){let auto=autoShopping(),inventoryGroups=new Map(INV_CATS.map(c=>[c,[]]));state.inventory.forEach(x=>(inventoryGroups.get(x.category)||inventoryGroups.get('常温')).push(x));let groups=INV_CATS.map(c=>{const items=inventoryGroups.get(c),key=`inventory:${c}`,folded=isFolded(key);return `${foldHeader(key,c,`${items.length} 项`)}<div class="foldBody" ${folded?'hidden':''}>${items.map(x=>`<div class="row"><span><b>${esc(x.name)}</b> · ${esc(x.amount)} ${esc(x.unit)}</span><span><button class="btn" data-edit-inv="${x.id}">编辑</button> <button class="btn" data-shop-from="${x.id}">采购</button> <button class="btn danger" data-remove-inv="${x.id}">删除</button></span></div>`).join('')||'<p class="muted">暂无食材</p>'}</div>`}).join('');const purchaseKey='purchase',purchaseFolded=isFolded(purchaseKey),purchaseCount=auto.length+state.shopping.length;body=`<section class="section"><div class="sectionTitle"><h2>食材库存</h2></div>${groups}${foldHeader(purchaseKey,'采购清单',`${purchaseCount} 项`)}<div class="foldBody" ${purchaseFolded?'hidden':''}><div class="actions purchaseActions"><button class="btn primary" data-new-shopping>手动添加采购</button><button class="btn danger" data-delete-selected-purchases>删除已勾选</button><button class="btn" data-stock-all>全部入库并清空</button><button class="btn danger" data-clear-shopping>全部清空</button></div>${auto.map(x=>{const selectKey=`auto:${x.sourceKey}`;return `<div class="row"><span><input type="checkbox" data-purchase-select="${esc(selectKey)}" ${selectedPurchases.has(selectKey)?'checked':''}> <b>${esc(x.name)}</b> · ${esc(x.amount)} ${esc(x.unit)} <span class="badge">计划缺少</span></span><span><button class="btn primary" data-auto-stock="${esc(x.sourceKey)}">编辑并入库</button> <button class="btn danger" data-auto-delete="${esc(x.sourceKey)}">删除</button></span></div>`}).join('')}${state.shopping.map(x=>{const selectKey=`manual:${x.id}`;return `<div class="row"><span><input type="checkbox" data-purchase-select="${esc(selectKey)}" ${selectedPurchases.has(selectKey)?'checked':''}> <b>${esc(x.name)}</b> · ${esc(x.amount||'')} ${esc(x.unit||'')}</span><span><button class="btn" data-edit-shopping="${x.id}">编辑</button> <button class="btn primary" data-manual-stock="${x.id}">加入库存</button> <button class="btn danger" data-remove-shop="${x.id}">删除</button></span></div>`}).join('')||(!auto.length?'<p class="muted">暂无待采购食材</p>':'')}</div></section>`;$('#app').innerHTML=shell(body,'库存与采购','inventory')}
else{let lc=lanConfig(),cols=gridColumns();body=`<section class="section"><div class="setting"><b>私人账号</b><p class="muted">当前用户：${esc(currentAuth?.username||'')}</p><button class="btn" data-lock>立即锁定</button></div><div class="setting"><b>首页菜谱卡片</b><p class="muted">选择首页每行显示的菜谱数量。</p><div class="actions">${[2,3,4].map(n=>`<button class="btn ${cols===n?'primary':''}" data-grid-cols="${n}">每行 ${n} 张</button>`).join('')}</div></div><div class="setting"><b>家庭局域网同步</b><p class="muted">电脑启动同步服务后，同一 Wi‑Fi 内可同步加密数据。电脑关闭时继续使用本机数据。</p><div class="field"><label>同步地址</label><input id="lanUrl" value="${esc(lc.url||'')}" placeholder="https://192.168.1.20:9443"></div><div class="field"><label>同步密钥</label><input id="lanToken" type="password" value="${esc(lc.token||'')}" placeholder="Windows 设置脚本生成的密钥"></div><div class="actions"><button class="btn" data-save-lan>保存设置</button><button class="btn primary" data-sync-now>立即同步</button></div><p id="syncStatus" class="muted">${esc(lc.status||'尚未同步')}</p></div><div class="setting"><b>本地加密数据</b><p class="muted">菜谱 ${state.recipes.length} 道；仅保留当前库存、未来 7 天计划和当前采购。</p><div class="actions"><button class="btn primary" data-export>导出完整备份</button><button class="btn" data-import>恢复备份</button><button class="btn" data-localize-images>保存网络图片供离线使用</button></div></div><div class="setting"><b>数据安全</b><p class="muted">本机采用双副本事务保存；局域网服务器只保存密码加密后的数据库。</p><button class="btn" data-storage>检查存储空间</button></div></section>`;$('#app').innerHTML=shell(body,'我的')}
if(view==='我的'){const lock=$('[data-lock]');if(lock&&!$('[data-change-username]'))lock.insertAdjacentHTML('beforebegin','<button class="btn" data-change-username>更改用户名</button> ')}
}
function days(n){let a=[];for(let i=0;i<n;i++){let d=new Date();d.setDate(d.getDate()+i);let key=d.toLocaleDateString('sv-SE');a.push({key,label:`${d.getMonth()+1}月${d.getDate()}日 ${['日','一','二','三','四','五','六'][d.getDay()]}`})}return a}
function planIds(key){let p=state.plans[key];return Array.isArray(p)?p:[]}
function ledgerKey(day,rid){return `${day}|${rid}`}
function applyPlanInventory(day,rid){const key=ledgerKey(day,rid);if(state.planLedger[key])return;const r=state.recipes.find(x=>x.id===rid);if(!r)return;state.planLedger[key]=r.ingredients.filter(x=>x.name?.trim()).map(x=>{const n=Number(x.amount),numeric=Number.isFinite(n)&&x.amount!=='';let consumed=0;if(numeric){const stock=state.inventory.find(i=>i.name.trim().toLowerCase()===x.name.trim().toLowerCase()&&(i.unit||'')===(x.unit||''));if(stock){const available=Math.max(0,Number(stock.amount)||0);consumed=Math.min(available,n);stock.amount=String(Math.max(0,available-consumed))}}return{name:x.name.trim(),unit:x.unit||'',required:numeric?n:0,consumed,shortage:numeric?Math.max(0,n-consumed):0,note:numeric?'':x.amount||'适量'}})}
function releasePlanInventory(day,rid){const key=ledgerKey(day,rid),rows=state.planLedger[key]||[];rows.forEach(x=>{if(!(x.consumed>0))return;let stock=state.inventory.find(i=>i.name.trim().toLowerCase()===x.name.toLowerCase()&&(i.unit||'')===(x.unit||''));if(!stock){stock={id:id(),name:x.name,amount:'0',unit:x.unit,category:'常温'};state.inventory.push(stock)}stock.amount=String((Number(stock.amount)||0)+x.consumed)});delete state.planLedger[key]}
function migratePlanLedger(){if(state.ledgerReady)return false;Object.entries(state.plans).forEach(([day,ids])=>Array.isArray(ids)&&ids.forEach(rid=>applyPlanInventory(day,rid)));state.ledgerReady=true;return true}
function autoShopping(){const map=new Map();Object.values(state.planLedger).flat().forEach(x=>{if(!(x.shortage>0)&&!x.note)return;const key=`${x.name.toLowerCase()}|${x.unit}`;if(!map.has(key))map.set(key,{sourceKey:key,name:x.name,unit:x.unit,amount:0,notes:[]});const row=map.get(key);row.amount+=x.shortage||0;if(x.note)row.notes.push(x.note)});return [...map.values()].map(x=>({...x,amount:[x.amount||'',...new Set(x.notes)].filter(String).join(' + ')})).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))}
function clearAutoItem(sourceKey){Object.values(state.planLedger).flat().forEach(x=>{if(`${x.name.toLowerCase()}|${x.unit}`===sourceKey){x.shortage=0;x.note=''}})}
function deleteSelectedPurchases(){if(!selectedPurchases.size)return toast('请先勾选要删除的采购食材');if(!confirm(`确定删除已勾选的 ${selectedPurchases.size} 项采购食材？`))return;const manualIds=new Set();for(const key of selectedPurchases){if(key.startsWith('auto:'))clearAutoItem(key.slice(5));else if(key.startsWith('manual:'))manualIds.add(key.slice(7))}state.shopping=state.shopping.filter(x=>!manualIds.has(x.id));selectedPurchases.clear();save(true);render();toast('已删除勾选的采购食材')}
function purchaseEditor(type,key){let x;if(type==='auto')x=autoShopping().find(i=>i.sourceKey===key);else{x=state.shopping.find(i=>i.id===key);if(x){const m=String(x.amount||'').match(/^\s*([\d.]+)\s*(.*)$/);x={...x,amount:m?.[1]||x.amount||'',unit:x.unit||m?.[2]||''}}}if(!x)return;overlay={type:'purchase',sourceType:type,sourceKey:key,draft:x};document.querySelector('.overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>取消</button><div class="spacer"></div><button class="btn primary" data-save-purchase>加入库存</button></div><h1>采购食材入库</h1><div class="field"><label>食材名称</label><input id="purchaseName" value="${esc(x.name)}"></div><div class="itemGrid"><div class="field"><label>数量</label><input id="purchaseAmount" inputmode="decimal" value="${esc(Number(x.amount)>0?x.amount:'')}" placeholder="请输入数字"></div><div class="field"><label>单位</label><input id="purchaseUnit" value="${esc(x.unit||'')}" placeholder="个、克、包"></div></div><div class="field"><label>存放分类</label><select id="purchaseCategory">${INV_CATS.map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${Number(x.amount)>0?'':`<p class="muted">原采购用量为“${esc(x.amount)}”，请填写实际购买的数字数量。</p>`}</div></section>`)}
function shoppingEditor(sid){const old=state.shopping.find(x=>x.id===sid),x=old?{...old}:{id:id(),name:'',amount:'',unit:'',category:'常温',done:false};overlay={type:'shopping-edit',draft:x,isNew:!old};document.querySelector('.overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>取消</button><div class="spacer"></div><button class="btn primary" data-save-shopping>保存采购项</button></div><h1>${old?'编辑采购食材':'手动添加采购'}</h1><div class="field"><label>食材名称</label><input id="shoppingName" value="${esc(x.name)}" placeholder="例如：鸡蛋"></div><div class="itemGrid"><div class="field"><label>数量</label><input id="shoppingAmount" inputmode="decimal" value="${esc(x.amount)}" placeholder="1"></div><div class="field"><label>单位</label><input id="shoppingUnit" value="${esc(x.unit||'')}" placeholder="盒"></div></div><div class="field"><label>入库分类</label><select id="shoppingCategory">${INV_CATS.map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select></div></div></section>`)}
function saveShoppingDraft(){const name=$('#shoppingName').value.trim(),amount=$('#shoppingAmount').value.trim(),unit=$('#shoppingUnit').value.trim(),category=$('#shoppingCategory').value;if(!name)return toast('请填写食材名称');const x={...overlay.draft,name,amount,unit,category,done:false};if(overlay.isNew)state.shopping.push(x);else state.shopping=state.shopping.map(i=>i.id===x.id?x:i);save(true);closeOverlay();render();toast('采购项已保存')}
function savePurchaseItem(){const name=$('#purchaseName').value.trim(),amount=Number($('#purchaseAmount').value),unit=$('#purchaseUnit').value.trim(),category=$('#purchaseCategory').value;if(!name||!(amount>0))return toast('请填写食材名称和数字数量');let stock=state.inventory.find(i=>i.name.trim().toLowerCase()===name.toLowerCase()&&(i.unit||'')===unit);if(!stock){stock={id:id(),name,amount:'0',unit,category};state.inventory.push(stock)}stock.amount=String((Number(stock.amount)||0)+amount);stock.category=category;if(overlay.sourceType==='auto')clearAutoItem(overlay.sourceKey);else state.shopping=state.shopping.filter(i=>i.id!==overlay.sourceKey);save(true);closeOverlay();render();toast('已加入库存并删除该采购项')}
function clearShopping(addToInventory=false){if(addToInventory){[...autoShopping(),...state.shopping].forEach(x=>{const raw=String(x.amount||''),m=raw.match(/^\s*([\d.]+)\s*(.*)$/),amount=m?Number(m[1]):0,unit=x.unit||m?.[2]||'';if(!(amount>0))return;let stock=state.inventory.find(i=>i.name.trim().toLowerCase()===x.name.trim().toLowerCase()&&(i.unit||'')===unit);if(!stock){stock={id:id(),name:x.name,amount:'0',unit,category:'常温'};state.inventory.push(stock)}stock.amount=String((Number(stock.amount)||0)+amount)})}Object.values(state.planLedger).flat().forEach(x=>{x.shortage=0;x.note=''});state.shopping=[];save(true);render();toast(addToInventory?'采购食材已入库并清空':'采购清单已清空')}
function planResultsHtml(key,q=''){const selected=planIds(key),results=searchRecipes(q,true);return results.map(r=>`<div class="row"><span><b>${esc(r.name)}</b><br><small class="muted">${esc(r.cat)} · ${esc(r.ingredients.map(x=>x.name).join('、'))}</small></span><button class="btn ${selected.includes(r.id)?'':'primary'}" data-plan-add="${r.id}" ${selected.includes(r.id)?'disabled':''}>${selected.includes(r.id)?'已添加':'添加'}</button></div>`).join('')||'<p class="muted">没有匹配的菜谱</p>'}
function planPicker(key,q=''){overlay={type:'plan',key,q};document.querySelector('.overlay')?.remove();const selected=planIds(key);document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>完成</button><div class="spacer"></div></div><h1>选择计划菜谱</h1><input class="search" id="planSearch" value="${esc(q)}" placeholder="精准搜索菜名或食材" autocomplete="off" enterkeyhint="search"><h2>已选择</h2><div id="planSelected">${selected.map(rid=>{let r=state.recipes.find(x=>x.id===rid);return r?`<div class="row"><b>${esc(r.name)}</b><button class="btn danger" data-plan-remove="${rid}">移除</button></div>`:''}).join('')||'<p class="muted">尚未选择菜谱</p>'}</div><h2>搜索结果</h2><div id="planResults">${planResultsHtml(key,q)}</div></div></section>`);requestAnimationFrame(()=>$('#planSearch')?.focus())}
function recipePlanPicker(rid){const r=state.recipes.find(x=>x.id===rid);if(!r)return;overlay={type:'recipe-plan',id:rid};document.querySelector('.overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>取消</button><div class="spacer"></div></div><h1>添加“${esc(r.name)}”到计划</h1><p class="muted">选择今天或未来 6 天中的一天。</p>${days(7).map(d=>{const added=planIds(d.key).includes(rid);return `<div class="row"><b>${d.label}</b><button class="btn ${added?'':'primary'}" data-detail-plan-day="${d.key}" ${added?'disabled':''}>${added?'已添加':'添加到当天'}</button></div>`}).join('')}</div></section>`)}
function inventoryEditor(iid){const x=state.inventory.find(i=>i.id===iid)||{id:id(),name:'',amount:'',unit:'',category:'常温'};overlay={type:'inventory',draft:{...x},isNew:!iid};document.querySelector('.overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>取消</button><div class="spacer"></div><button class="btn primary" data-save-inv>保存</button></div><h1>${iid?'编辑库存':'添加食材'}</h1><div class="field"><label>食材名称</label><input id="invName" value="${esc(x.name)}" placeholder="例如：鸡蛋"></div><div class="itemGrid"><div class="field"><label>数量</label><input id="invAmount" value="${esc(x.amount)}" placeholder="1"></div><div class="field"><label>单位</label><input id="invUnit" value="${esc(x.unit)}" placeholder="盒"></div></div><div class="field"><label>存放分类</label><select id="invCategory">${INV_CATS.map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select></div></div></section>`)}
function detail(rid,cook=false){const r=state.recipes.find(x=>x.id===rid);if(!r)return;r.lastUsed=Date.now();saveLater();overlay={type:'detail',id:rid};const ingredients=r.ingredients.map(x=>`<label class="listItem"><input type="checkbox"> ${esc(x.name)} ${esc(x.amount)} ${esc(x.unit)}</label>`).join('');const steps=r.steps.map((x,i)=>`<div class="listItem"><label><input type="checkbox"> <b>${i+1}.</b> ${esc(x.text)}</label>${x.photo?`<img class="stepPhoto" src="${x.photo}" alt="步骤 ${i+1}" loading="lazy" decoding="async">`:''}</div>`).join('');document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner ${cook?'cook':''}"><div class="overlayBar"><button class="btn" data-close>← 返回</button><div class="spacer"></div>${cook?'<button class="btn" data-timer>⏱ 计时</button>':`<button class="btn primary" data-add-detail-plan="${rid}">添加到计划</button><button class="btn" data-copy="${rid}">复制</button><button class="btn" data-edit="${rid}">编辑</button>`}</div><h1>${esc(r.name)}</h1><span class="badge">${esc(r.cat)}</span><p class="muted">${esc(r.description||'')}</p>${photo(r.photo)}<h2>食材</h2>${ingredients||'<p class="muted">未填写</p>'}<h2>步骤</h2>${steps||'<p class="muted">未填写</p>'}<div class="actions">${cook?`<button class="btn" data-kitchen="${rid}">退出厨房模式</button>`:`<button class="btn primary" data-kitchen="${rid}">进入厨房模式</button><button class="btn danger" data-delete="${rid}">删除</button>`}</div><div id="timerBox"></div></div></section>`)}
function editor(rid){const old=state.recipes.find(x=>x.id===rid);const r=old?structuredClone(old):{id:id(),name:'',description:'',cat:'荤菜',photo:'',favorite:false,ingredients:[],steps:[],createdAt:Date.now()};overlay={type:'edit',draft:r,isNew:!old};drawEditor()}
function drawEditor(){document.querySelector('.overlay')?.remove();const r=overlay.draft;document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><div class="overlayInner"><div class="overlayBar"><button class="btn" data-close>取消</button><div class="spacer"></div><button class="btn primary" data-save-recipe>保存</button></div><h1>${overlay.isNew?'新增菜谱':'编辑菜谱'}</h1><div class="field"><label>封面照片</label><input type="file" accept="image/*" data-photo="cover">${r.photo?`<img class="stepPhoto" src="${r.photo}">`:''}</div><div class="field"><label>名称</label><input id="eName" value="${esc(r.name)}" placeholder="例如：红烧鸡翅"></div><div class="field"><label>描述</label><textarea id="eDesc" rows="3">${esc(r.description)}</textarea></div><div class="field"><label>分类</label><select id="eCat">${CATS.slice(2).map(x=>`<option ${r.cat===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="sectionTitle"><h2>食材</h2><button class="btn" data-add-ing>＋ 添加</button></div>${r.ingredients.map((x,i)=>`<div class="itemEditor"><div class="itemGrid"><input data-ing="name" data-i="${i}" value="${esc(x.name)}" placeholder="食材"><input data-ing="amount" data-i="${i}" value="${esc(x.amount)}" placeholder="用量"><input data-ing="unit" data-i="${i}" value="${esc(x.unit)}" placeholder="单位"></div><button class="btn danger" data-del-ing="${i}">删除</button></div>`).join('')}<div class="sectionTitle"><h2>步骤</h2><button class="btn" data-add-step>＋ 添加</button></div>${r.steps.map((x,i)=>`<div class="itemEditor"><b>第 ${i+1} 步</b><textarea class="search" data-step-text="${i}" rows="3" placeholder="描述做法">${esc(x.text)}</textarea><input type="file" accept="image/*" data-step-photo="${i}">${x.photo?`<img class="stepPhoto" src="${x.photo}">`:''}<div class="actions"><button class="btn" data-move-step="${i}" data-dir="-1">上移</button><button class="btn" data-move-step="${i}" data-dir="1">下移</button><button class="btn danger" data-del-step="${i}">删除</button></div></div>`).join('')}</div></section>`)}
async function imageData(file){if(!file)return'';if(file.size>25*1024*1024)throw Error('图片过大');const url=URL.createObjectURL(file),img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=url});const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);return c.toDataURL('image/jpeg',.8)}
async function localizeRemoteImages(){const targets=[];state.recipes.forEach(r=>{if(/^https?:\/\//.test(r.photo||''))targets.push({owner:r,key:'photo',name:r.name});r.steps.forEach((s,i)=>{if(/^https?:\/\//.test(s.photo||''))targets.push({owner:s,key:'photo',name:`${r.name}步骤${i+1}`})})});if(!targets.length)return toast('所有图片都已经保存在本机');if(!confirm(`将下载 ${targets.length} 张网络图片并写入加密菜谱，完成前请保持电脑服务和网络开启。是否继续？`))return;let ok=0,failed=0;for(const item of targets){setLanStatus(`正在保存离线图片 ${ok+failed+1}/${targets.length}：${item.name}`);try{const response=await lanFetch(`/api/image?url=${encodeURIComponent(item.owner[item.key])}`);if(!response.ok)throw Error(`下载失败（${response.status}）`);item.owner[item.key]=await imageData(await response.blob());ok++;if(ok%5===0)await save()}catch(e){console.error(item.name,e);failed++}}if(ok)await save();render();setLanStatus(`离线图片完成：成功 ${ok} 张，失败 ${failed} 张`);toast(failed?`已保存 ${ok} 张，${failed} 张失败，可稍后重试`:`${ok} 张图片已保存到本机，可断网使用`)}
function syncDraft(){if(overlay?.type!=='edit')return;const r=overlay.draft;r.name=$('#eName')?.value??r.name;r.description=$('#eDesc')?.value??r.description;r.cat=$('#eCat')?.value??r.cat;document.querySelectorAll('[data-ing]').forEach(el=>r.ingredients[+el.dataset.i][el.dataset.ing]=el.value);document.querySelectorAll('[data-step-text]').forEach(el=>r.steps[+el.dataset.stepText].text=el.value)}
function closeOverlay(){document.querySelector('.overlay')?.remove();overlay=null;if(timer){clearInterval(timer.interval);timer=null}}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`家庭厨房完整备份-${new Date().toLocaleDateString('sv-SE')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('备份已导出')}
let lanSyncTimer;
function setLanStatus(status,extra={}){const c={...lanConfig(),...extra,status};localStorage.setItem('family-kitchen-lan',JSON.stringify(c));const el=$('#syncStatus');if(el)el.textContent=status}
function saveLanSettings(){const url=$('#lanUrl').value.trim().replace(/\/$/,''),token=$('#lanToken').value.trim();if(!url.startsWith('https://')||!token)return toast('请填写 HTTPS 同步地址和同步密钥');const old=lanConfig();localStorage.setItem('family-kitchen-lan',JSON.stringify({...old,url,token,status:'设置已保存'}));toast('局域网同步设置已保存')}
async function lanFetch(path,options={}){const c=lanConfig();if(!c.url||!c.token)throw Error('请先填写同步地址和密钥');return fetch(c.url+path,{...options,headers:{'Authorization':`Bearer ${c.token}`,'Content-Type':'application/json',...(options.headers||{})}})}
async function applyServerPackage(pkg){if(!pkg?.auth||!pkg?.vault)throw Error('家庭电脑尚无同步数据');await dbRestorePackage(pkg);currentAuth=pkg.auth;setLanStatus(`已取得家庭电脑数据 · 版本 ${pkg.revision}`,{revision:pkg.revision});sessionKey=null;state=normalize();authScreen('unlock',currentAuth)}
let syncBridgeWindow=null;
async function openSyncBridge(){const c=lanConfig();if(!c.url||!c.token)throw Error('请先填写同步地址和密钥');syncBridgeWindow=window.open('about:blank','familyKitchenSync');if(!syncBridgeWindow)throw Error('请允许打开同步窗口');setLanStatus('正在打开家庭电脑同步连接页…');try{const auth=await dbGet('auth'),vault=await dbGet('vault');if(!auth||!vault)throw Error('本机没有可同步的数据');syncBridgeWindow.location.replace(`${c.url}/sync-bridge?origin=${encodeURIComponent(location.origin)}`)}catch(e){syncBridgeWindow.close();throw e}}
addEventListener('message',async event=>{const c=lanConfig();let expected;try{expected=new URL(c.url).origin}catch{return}if(event.origin!==expected)return;const message=event.data||{};if(message.type==='family-kitchen-sync-ready'){const auth=await dbGet('auth'),vault=await dbGet('vault');syncBridgeWindow?.postMessage({type:'family-kitchen-sync-data',token:c.token,baseRevision:Number(c.revision||0),auth,vault},expected);setLanStatus('正在通过家庭网络传输加密数据…')}else if(message.type==='family-kitchen-sync-success'){setLanStatus(`同步成功 · 版本 ${message.revision}`,{revision:message.revision});toast('局域网同步成功')}else if(message.type==='family-kitchen-sync-server'){await applyServerPackage(message.pkg)}else if(message.type==='family-kitchen-sync-error'){setLanStatus(`同步未完成：${message.message}`);toast(message.message)} });
async function syncNow(silent=false){try{const c=lanConfig();if(location.origin!==new URL(c.url).origin){if(silent)return;return await openSyncBridge()}const auth=await dbGet('auth'),vault=await dbGet('vault');if(!auth||!vault)throw Error('本机没有可同步的数据');setLanStatus('正在同步…');let res=await lanFetch('/api/vault',{method:'PUT',body:JSON.stringify({baseRevision:Number(c.revision||0),auth,vault})});if(res.status===409){const conflict=await res.json();if(silent){setLanStatus('检测到两台设备都有修改，请点“立即同步”处理冲突');return}if(confirm('家庭电脑和当前设备都有新修改。\n\n确定：使用家庭电脑版本覆盖本机\n取消：保留本机版本并覆盖家庭电脑'))return applyServerPackage(conflict.server);res=await lanFetch('/api/vault',{method:'PUT',body:JSON.stringify({force:true,baseRevision:Number(c.revision||0),auth,vault})})}if(!res.ok)throw Error(`同步失败（${res.status}）`);const out=await res.json();setLanStatus(`同步成功 · 版本 ${out.revision}`,{revision:out.revision});if(!silent)toast('局域网同步成功')}catch(e){setLanStatus(`同步未完成：${e.message}`);if(!silent)toast(e.message)}}
function scheduleLanSync(){clearTimeout(lanSyncTimer);if(lanConfig().url)lanSyncTimer=setTimeout(()=>syncNow(true),5000)}
async function restoreFromLan(){const old=lanConfig(),url=(prompt('家庭电脑同步地址',old.url||'https://192.168.1.20:9443')||'').trim().replace(/\/$/,''),token=(prompt('同步密钥',old.token||'')||'').trim();if(!url||!token)return;localStorage.setItem('family-kitchen-lan',JSON.stringify({url,token,revision:0,status:'正在连接…'}));try{const res=await lanFetch('/api/vault');if(!res.ok)throw Error(`连接失败（${res.status}）`);await applyServerPackage(await res.json())}catch(e){toast(`无法从家庭电脑恢复：${e.message}`)}}
let detailSwipe=null;
document.addEventListener('touchstart',e=>{if(overlay?.type!=='detail'||e.touches.length!==1||e.target.closest('button,input,textarea,select,a'))return;const p=e.touches[0];detailSwipe={x:p.clientX,y:p.clientY,time:Date.now()}},{passive:true});
document.addEventListener('touchend',e=>{if(!detailSwipe||overlay?.type!=='detail'){detailSwipe=null;return}const p=e.changedTouches[0],dx=p.clientX-detailSwipe.x,dy=p.clientY-detailSwipe.y,duration=Date.now()-detailSwipe.time,leftSwipe=dx<-90,rightSwipe=dx>90;detailSwipe=null;if(duration>700||Math.abs(dy)>60||Math.abs(dx)<Math.abs(dy)*1.4||(!leftSwipe&&!rightSwipe))return;const currentId=overlay.id,panel=document.querySelector('.overlay');if(!panel)return;if(leftSwipe){const index=state.recipes.findIndex(r=>r.id===currentId),next=state.recipes[index+1];if(!next)return toast('已经是最后一道食谱');panel.style.transition='transform .14s ease-out,opacity .14s ease-out';panel.style.transform='translateX(-18%)';panel.style.opacity='0';setTimeout(()=>{if(overlay?.type==='detail'&&overlay.id===currentId){closeOverlay();detail(next.id)}},140);return}panel.style.transition='transform .14s ease-out,opacity .14s ease-out';panel.style.transform='translateX(18%)';panel.style.opacity='0';setTimeout(()=>{if(overlay?.type==='detail'&&overlay.id===currentId){closeOverlay();render()}},140)},{passive:true});
const MAIN_VIEWS=['首页','计划','库存','搜索','我的'];let mainSwipe=null,suppressSwipeClickUntil=0;
document.addEventListener('touchstart',e=>{if(overlay||e.touches.length!==1||!e.target.closest('.shell')||e.target.closest('input,textarea,select,a,.tabs,.bottom'))return;const p=e.touches[0];mainSwipe={x:p.clientX,y:p.clientY,time:Date.now()}},{passive:true});
document.addEventListener('touchend',e=>{if(!mainSwipe||overlay){mainSwipe=null;return}const p=e.changedTouches[0],dx=p.clientX-mainSwipe.x,dy=p.clientY-mainSwipe.y,duration=Date.now()-mainSwipe.time;mainSwipe=null;if(duration>700||Math.abs(dx)<90||Math.abs(dy)>60||Math.abs(dx)<Math.abs(dy)*1.4)return;suppressSwipeClickUntil=Date.now()+500;if(view==='首页'){const current=CATS.indexOf(cat),next=(current+(dx<0?1:-1)+CATS.length)%CATS.length;cat=CATS[next];render();goTop();return}const current=MAIN_VIEWS.indexOf(view),next=current+(dx<0?1:-1);if(next<0)return toast('已经是第一个页面');if(next>=MAIN_VIEWS.length)return toast('已经是最后一个页面');view=MAIN_VIEWS[next];cat='全部';render();goTop()},{passive:true});
document.addEventListener('click',e=>{if(Date.now()<suppressSwipeClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-open],[data-plan]');if(!t)return;
if(t.dataset.view){view=t.dataset.view;cat='全部';render();goTop()}else if(t.dataset.cat){cat=t.dataset.cat;render();goTop()}else if(t.dataset.fold){toggleFold(t.dataset.fold)}else if(t.dataset.open)detail(t.dataset.open);else if(t.dataset.fav){const r=state.recipes.find(x=>x.id===t.dataset.fav);r.favorite=!r.favorite;save();render()}else if(t.dataset.action==='recipe')editor();else if(t.dataset.action==='inventory'){let name=prompt('食材名称');if(name){state.inventory.push({id:id(),name,amount:prompt('数量','1')||'',unit:prompt('单位（可空）','份')||'',category:'常温'});save();render()}}else if(t.hasAttribute('data-close')){closeOverlay();render()}else if(t.dataset.edit){closeOverlay();editor(t.dataset.edit)}else if(t.dataset.addDetailPlan){const rid=t.dataset.addDetailPlan;closeOverlay();recipePlanPicker(rid)}else if(t.dataset.detailPlanDay){const rid=overlay.id,day=t.dataset.detailPlanDay,a=planIds(day);if(!a.includes(rid)){applyPlanInventory(day,rid);state.plans[day]=[...a,rid];await save(true)}closeOverlay();detail(rid);toast('已添加到当天计划，采购清单已更新')}else if(t.dataset.kitchen){const entering=!document.querySelector('.cook');closeOverlay();detail(t.dataset.kitchen,entering)}else if(t.dataset.copy){const r=state.recipes.find(x=>x.id===t.dataset.copy),x=structuredClone(r);x.id=id();x.name+='（副本）';x.createdAt=x.updatedAt=Date.now();state.recipes.unshift(x);save(true);closeOverlay();render()}else if(t.dataset.delete&&confirm('确定删除这道菜？此操作无法撤销。')){state.recipes=state.recipes.filter(x=>x.id!==t.dataset.delete);save(true);closeOverlay();render()}else if(t.hasAttribute('data-add-ing')){syncDraft();overlay.draft.ingredients.push({id:id(),name:'',amount:'',unit:''});drawEditor()}else if(t.dataset.delIng!==undefined){syncDraft();overlay.draft.ingredients.splice(+t.dataset.delIng,1);drawEditor()}else if(t.hasAttribute('data-add-step')){syncDraft();overlay.draft.steps.push({id:id(),text:'',photo:''});drawEditor()}else if(t.dataset.delStep!==undefined){syncDraft();overlay.draft.steps.splice(+t.dataset.delStep,1);drawEditor()}else if(t.dataset.moveStep!==undefined){syncDraft();let i=+t.dataset.moveStep,j=i+(+t.dataset.dir);if(j>=0&&j<overlay.draft.steps.length)[overlay.draft.steps[i],overlay.draft.steps[j]]=[overlay.draft.steps[j],overlay.draft.steps[i]];drawEditor()}else if(t.hasAttribute('data-save-recipe')){syncDraft();const r=overlay.draft;if(!r.name.trim())return toast('请填写菜谱名称');r.updatedAt=Date.now();if(overlay.isNew)state.recipes.unshift(r);else state.recipes=state.recipes.map(x=>x.id===r.id?r:x);await save(true);closeOverlay();render()}else if(t.dataset.plan){planPicker(t.dataset.plan)}else if(t.dataset.planAdd){const a=planIds(overlay.key);if(!a.includes(t.dataset.planAdd))state.plans[overlay.key]=[...a,t.dataset.planAdd];save();planPicker(overlay.key,overlay.q);toast('已添加，采购清单已更新')}else if(t.dataset.planRemove){state.plans[overlay.key]=planIds(overlay.key).filter(x=>x!==t.dataset.planRemove);if(!state.plans[overlay.key].length)delete state.plans[overlay.key];save();planPicker(overlay.key,overlay.q);toast('已移除，采购清单已更新')}else if(t.dataset.removeInv){state.inventory=state.inventory.filter(x=>x.id!==t.dataset.removeInv);save();render()}else if(t.dataset.shopFrom){const x=state.inventory.find(x=>x.id===t.dataset.shopFrom);state.shopping.push({id:id(),name:x.name,amount:x.amount||'',unit:x.unit||'',category:x.category||'常温',done:false});save();render()}else if(t.dataset.removeShop){state.shopping=state.shopping.filter(x=>x.id!==t.dataset.removeShop);save();render()}else if(t.hasAttribute('data-export'))exportData();else if(t.hasAttribute('data-import'))$('#restoreInput').click();else if(t.hasAttribute('data-localize-images'))await localizeRemoteImages();else if(t.hasAttribute('data-storage')){if(navigator.storage?.estimate){const x=await navigator.storage.estimate();toast(`已用 ${(x.usage/1048576).toFixed(1)} MB，可用额度约 ${(x.quota/1048576).toFixed(0)} MB`)}else toast('此浏览器不提供容量估算')}else if(t.hasAttribute('data-timer')){let m=Number(prompt('倒计时分钟数','10'));if(m>0)startTimer(m)}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-action="inventory"],[data-edit-inv],[data-save-inv]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.dataset.action==='inventory')inventoryEditor();else if(t.dataset.editInv)inventoryEditor(t.dataset.editInv);else{const name=$('#invName').value.trim();if(!name)return toast('请填写食材名称');const x={...overlay.draft,name,amount:$('#invAmount').value.trim(),unit:$('#invUnit').value.trim(),category:$('#invCategory').value};if(overlay.isNew)state.inventory.push(x);else state.inventory=state.inventory.map(i=>i.id===x.id?x:i);save(true);closeOverlay();render()}},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-plan-add],[data-plan-remove],[data-stock-all],[data-clear-shopping]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.dataset.planAdd){const day=overlay.key,a=planIds(day);if(!a.includes(t.dataset.planAdd)){applyPlanInventory(day,t.dataset.planAdd);state.plans[day]=[...a,t.dataset.planAdd]}save();planPicker(day,overlay.q);toast('已占用库存，仅缺少部分加入采购')}else if(t.dataset.planRemove){const day=overlay.key;releasePlanInventory(day,t.dataset.planRemove);state.plans[day]=planIds(day).filter(x=>x!==t.dataset.planRemove);if(!state.plans[day].length)delete state.plans[day];save();planPicker(day,overlay.q);toast('计划已移除，库存已退回')}else if(t.hasAttribute('data-stock-all')){if(confirm('把采购清单中的数字用量全部加入常温库存，并清空采购清单？'))clearShopping(true)}else if(confirm('确定清空全部采购清单？'))clearShopping(false)},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-auto-stock],[data-auto-delete],[data-manual-stock],[data-save-purchase],[data-new-shopping],[data-edit-shopping],[data-save-shopping]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.dataset.autoStock)purchaseEditor('auto',t.dataset.autoStock);else if(t.dataset.manualStock)purchaseEditor('manual',t.dataset.manualStock);else if(t.hasAttribute('data-save-purchase'))savePurchaseItem();else if(t.hasAttribute('data-new-shopping'))shoppingEditor();else if(t.dataset.editShopping)shoppingEditor(t.dataset.editShopping);else if(t.hasAttribute('data-save-shopping'))saveShoppingDraft();else if(confirm('确定删除这一条采购项？')){clearAutoItem(t.dataset.autoDelete);save(true);render()}},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-delete-selected-purchases]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();deleteSelectedPurchases()},true);
let textSearchTimer=null;
function updateTextSearch(input,immediate=false){if(input._composing)return;const value=input.value;if(input.id==='searchBox')query=value;else if(input.id==='planSearch'&&overlay?.type==='plan')overlay.q=value;else return;clearTimeout(textSearchTimer);const update=()=>{if(input.id==='searchBox'){const results=$('#searchResults');if(results)results.innerHTML=grid(searchRecipes(value))}else if(input.id==='planSearch'&&overlay?.type==='plan'){const results=$('#planResults');if(results)results.innerHTML=planResultsHtml(overlay.key,value)}};if(immediate)update();else textSearchTimer=setTimeout(()=>requestAnimationFrame(update),90)}
document.addEventListener('compositionstart',e=>{if(e.target.matches('#searchBox,#planSearch'))e.target._composing=true});
document.addEventListener('compositionend',e=>{if(e.target.matches('#searchBox,#planSearch')){e.target._composing=false;updateTextSearch(e.target,true)}});
document.addEventListener('input',e=>{if(e.target.matches('#searchBox,#planSearch'))updateTextSearch(e.target)});
document.addEventListener('click',e=>{if(e.target.closest('[data-lock]')){sessionKey=null;state=normalize();authScreen('unlock',currentAuth)}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-change-username]')){e.preventDefault();e.stopImmediatePropagation();changeUsername()}},true);
document.addEventListener('click',e=>{const button=e.target.closest('[data-grid-cols]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const columns=Number(button.dataset.gridCols);if(![2,3,4].includes(columns))return;localStorage.setItem('family-kitchen-grid-columns',String(columns));render();toast(`首页已设置为每行 ${columns} 张`)},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-save-lan],[data-sync-now],[data-lan-restore]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.hasAttribute('data-save-lan'))saveLanSettings();else if(t.hasAttribute('data-sync-now')){saveLanSettings();syncNow(false)}else restoreFromLan()},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='authForm')return;e.preventDefault();const mode=e.target.dataset.mode,user=$('#authUser').value.trim(),pass=$('#authPass').value,err=$('#authError');err.textContent='';try{if(mode==='setup'){if(pass!==$('#authConfirm').value)throw Error('两次输入的密码不一致');await setupAccount(user,pass)}else await unlockAccount(user,pass)}catch(ex){console.error(ex);err.textContent=mode==='setup'?'创建失败，请重试':'用户名或密码不正确'}});
document.addEventListener('change',async e=>{if(e.target.dataset.purchaseSelect){const key=e.target.dataset.purchaseSelect;if(e.target.checked)selectedPurchases.add(key);else selectedPurchases.delete(key)}else if(e.target.dataset.photo==='cover'){try{syncDraft();overlay.draft.photo=await imageData(e.target.files[0]);drawEditor()}catch{toast('图片读取失败或文件过大')}}else if(e.target.dataset.stepPhoto!==undefined){try{syncDraft();overlay.draft.steps[+e.target.dataset.stepPhoto].photo=await imageData(e.target.files[0]);drawEditor()}catch{toast('图片读取失败或文件过大')}}});
function startTimer(m){if(timer)clearInterval(timer.interval);timer={end:Date.now()+m*60000};const tick=()=>{let left=Math.max(0,Math.ceil((timer.end-Date.now())/1000)),el=$('#timerBox');if(el)el.innerHTML=`<div class="timer"><strong>${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}</strong><span>${left?'烹饪计时中':'时间到！'}</span></div>`;if(!left){clearInterval(timer.interval);navigator.vibrate?.([300,150,300]);alert('倒计时结束')}};tick();timer.interval=setInterval(tick,1000)}
$('#restoreInput').addEventListener('change',async e=>{const previous=state;try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.recipes))throw Error('备份文件格式不正确');if(confirm('恢复备份将覆盖当前全部数据，确定继续？')){state=normalize(x);await save();render();toast('备份恢复完成，刷新后数据仍会保留')}}catch(err){state=previous;render();toast(err?.message==='备份文件格式不正确'?err.message:'恢复失败，原数据已保留，请勿刷新')}finally{e.target.value=''}});
async function init(){try{await navigator.storage?.persist?.();db=await openDB();currentAuth=await dbGet('auth');if(currentAuth)authScreen('unlock',currentAuth);else{pendingLegacy=await dbGet('main');if(!pendingLegacy){try{pendingLegacy=JSON.parse(localStorage.getItem('family-recipes-v1')||'null')}catch{}}authScreen('setup')}}catch(e){console.error(e);$('#app').innerHTML='<div class="empty"><b>无法打开本地数据库</b><br>请检查 Safari 是否处于无痕模式或存储空间是否已满。</div>'}if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(console.warn)}
addEventListener('online',()=>toast('已恢复网络连接'));addEventListener('offline',()=>toast('已离线，仍可继续使用'));init();
